arguments.command:
cd /home/runner/.shurik/logs/igor-makarov/beetle-in-the-anthill/friends-4/recovery/ && python3 - <<'EOF'
import json,glob,os,re
for f in sorted(glob.glob('*.json')):
    d=json.load(open(f))
    txt=json.dumps(d)
    hits=[]
    for kw in ['fast-forward','fast forward','non-fast','##[error]','Error:','failed to','Cannot','diverg']:
        for m in re.finditer(re.escape(kw), txt):
            hits.append((kw, txt[max(0,m.start()-300):m.start()+400]))
    if hits:
        print('=====',f, d.get('iteration'), d.get('startedAt'))
        for kw,h in hits[-3:]:
            print('  >>',kw,'::',h.replace('\\n','\n')[:700])
        print()
EOF

